# --------------------------------------------------------------------------
# Library
# --------------------------------------------------------------------------
if _anv_store is None:
    st.error("The quote library module failed to load, so nothing can be saved.")
    st.stop()


@st.cache_resource(show_spinner=False)
def _get_store(folder: str):
    return _anv_store.Store(folder or None)


STORE = _get_store(_secret("STORE_DIR"))


@st.cache_resource(show_spinner=False)
def _get_archive(share_dir: str, local_dir: str):
    """Timestamped run folders: the Posit output share when it is writable, else a local folder."""
    return _anv_store.Archive(share_dir or None, local_dir)


ARCHIVE = _get_archive(_secret("ARCHIVE_DIR"), str(STORE.path.parent / "runs"))



# --------------------------------------------------------------------------
# Library durability. Every save is verified and copied to the shared folder AND to mirrors on this server; on every
# start / library view / open, the database is rebuilt from whichever copy survived. Best-effort, never raises.
# --------------------------------------------------------------------------
def _sync_library(force: bool = False, only: str | None = None) -> dict:
    """Bring the database and every copy level, newest winning. Throttled to once every 30 s unless forced."""
    now = time.time()
    if not force and not only and now - ss.get("_sync_at", 0) < 30:
        return ss.get("sync_report") or {}
    try:
        if not only and not ARCHIVE.legacy_done() and now - ss.get("_legacy_try", 0) > 600:
            ss["_legacy_try"] = now                                   # older per-run folders: merged once, then marked
            try:
                ss["legacy_report"] = STORE.import_legacy(ARCHIVE)
                ARCHIVE.mark_legacy_done()
            except Exception as exc:                                  # noqa: BLE001
                ss["legacy_report"] = {"error": f"{type(exc).__name__}: {exc}"}
        rep = STORE.sync(ARCHIVE, only=only)
    except Exception as exc:                                          # noqa: BLE001
        rep = {"errors": [f"{type(exc).__name__}: {exc}"], "state": {}, "share": ARCHIVE.on_share, "unreadable": []}
    ss.setdefault("vault_state", {}).update(rep.get("state") or {})
    if not only:
        ss["_sync_at"] = now
        ss["sync_report"] = rep
    return rep


def _storage_banner(with_backup: bool = False) -> None:
    """Plain-English warnings when results are not as safe as they should be."""
    if not ARCHIVE.on_share:
        n = len(ARCHIVE.local_roots)
        st.warning(f"The shared folder is not usable, so results are being kept on this server only ({n} cop"
                   f"{'y' if n == 1 else 'ies'} in separate folders). That is fine day to day, but they can be lost if the "
                   "server's storage is cleared. Open **Storage health** on the Accounts page for the exact reason, and "
                   "download a backup file to be safe.")
        if with_backup:
            try:
                st.download_button("Download a backup of everything now", data=STORE.export_all(), key="bk_dl_banner",
                                   file_name=f"ANV_quote_library_{datetime.now():%Y%m%d_%H%M}.json",
                                   mime="application/json")
            except Exception:                                         # noqa: BLE001
                pass
    elif ARCHIVE.share_suspect:
        st.warning(f"The shared folder `{ARCHIVE.share_root}` did not exist and had to be created, and it does not sit on "
                   "a mounted drive. If the share is not mounted, saved results are only on this server.")
    if not STORE.durable:
        st.warning(f"The library database is in a {STORE.kind_note}. Results are also copied to other folders, but set "
                   "STORE_DIR to a permanent folder.")


def _save_badge() -> str:
    si = ss.get("save_info")
    if not si:
        return ""
    if not si.get("ok"):
        return '<span class="badge bad">Not saved</span>'
    if si.get("shared"):
        return f'<span class="badge ok">Saved {si["t"]} &middot; shared folder</span>'
    return f'<span class="badge warn">Saved {si["t"]} &middot; this server only</span>'


# --------------------------------------------------------------------------
# In-force portfolio registry: one entry per month ("as at" date), so the monthly in-force analysis is picked from a
# list instead of retyped. Saved in the shared run folder (so everyone sees it) and mirrored on this server.
# The short app ID (e.g. 65418) and the long analysis ID (e.g. 2667825) are interchangeable; once both are known
# the LONG one is what the pipeline uses, so no search is ever needed.
# --------------------------------------------------------------------------
INFORCE_FILE = "inforce_registry.json"


def _inforce_paths(write: bool = False) -> list:
    if write:
        try:
            ARCHIVE.refresh()                                   # the share can come and go
        except Exception:                                       # noqa: BLE001
            pass
    out = []
    roots = [ARCHIVE.root] + list(getattr(ARCHIVE, "local_roots", [])) + [STORE.path.parent]
    for r in roots:
        p = Path(r) / INFORCE_FILE
        if p not in out:
            out.append(p)
    return out


def _inforce_load() -> dict:
    """Newest copy wins (every copy is written together)."""
    best = {"months": {}, "updated": ""}
    for p in _inforce_paths():
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
        except Exception:                                       # noqa: BLE001
            continue
        if not isinstance(d, dict) or not isinstance(d.get("months"), dict):
            continue
        if str(d.get("updated", "")) >= best["updated"]:
            best = {"months": d["months"], "updated": str(d.get("updated", ""))}
    best["months"] = {k: m for k, m in best["months"].items()
                      if isinstance(m, dict) and str(m.get("id", "")).isdigit() and m.get("as_at") == k}
    return best


def _inforce_save(reg: dict) -> int:
    """Write the registry everywhere it can go. Returns how many copies were written."""
    reg["updated"] = datetime.now().isoformat(timespec="seconds")
    blob = json.dumps({"months": reg["months"], "updated": reg["updated"]}, indent=2)
    wrote = 0
    for p in _inforce_paths(write=True):
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
            tmp = p.with_name(p.name + ".tmp")
            tmp.write_text(blob, encoding="utf-8")
            os.replace(tmp, p)
            wrote += 1
        except Exception:                                       # noqa: BLE001
            continue
    return wrote


def _inforce_default_meta(default_id: str) -> dict:
    """The standing default. 65418 and 2667825 are the same analysis, so either one gives both."""
    d = re.sub(r"\D", "", str(default_id or "")) or DEFAULT_INFORCE_ANALYSIS_ID
    if d in (DEFAULT_INFORCE_ANALYSIS_ID, DEFAULT_INFORCE_LONG_ID):
        return {"as_at": "", "id": d, "app_id": DEFAULT_INFORCE_ANALYSIS_ID, "analysis_id": DEFAULT_INFORCE_LONG_ID,
                "name": DEFAULT_INFORCE_NAME, "default": True}
    long_ = len(d) >= 7
    return {"as_at": "", "id": d, "app_id": "" if long_ else d, "analysis_id": d if long_ else "", "name": "",
            "default": True}


def _inforce_effective_id(meta: dict) -> str:
    """The ID the pipeline uses: the long analysis ID whenever it is known (no search), else the short one."""
    return str(meta.get("analysis_id") or meta.get("id") or "")


def _inforce_ids(meta: dict) -> set:
    return {str(meta.get(k)) for k in ("id", "app_id", "analysis_id") if meta and meta.get(k)}


def _fmt_asat(iso: str) -> str:
    try:
        return date.fromisoformat(iso).strftime("%d/%m/%Y")
    except Exception:                                           # noqa: BLE001
        return iso or ""


def _inforce_label(meta: dict) -> str:
    ident = meta.get("app_id") or meta.get("id") or meta.get("analysis_id") or ""
    if meta.get("default"):
        return f"Default  -  {ident}"
    return f"As at {_fmt_asat(meta.get('as_at', ''))}  -  {ident}"


def _inforce_describe(meta: dict) -> str:
    bits = [f"as at {_fmt_asat(meta['as_at'])}" if meta.get("as_at") else "default"]
    if meta.get("app_id"):
        bits.append(f"app ID {meta['app_id']}")
    if meta.get("analysis_id"):
        bits.append(f"analysis {meta['analysis_id']}")
    if not meta.get("app_id") and not meta.get("analysis_id") and meta.get("id"):
        bits.append(f"ID {meta['id']}")
    if meta.get("name"):
        bits.append(meta["name"])
    return "  |  ".join(bits)


def _inforce_state():
    """Which entry is selected. Runs BEFORE the picker widget is drawn, so every part of the page agrees."""
    reg = ss["inforce_reg"]
    def_meta = _inforce_default_meta(_secret("INFORCE_ANALYSIS_ID") or DEFAULT_INFORCE_ANALYSIS_ID)
    opts = [m["as_at"] for m in sorted(reg["months"].values(), key=lambda m: m["as_at"], reverse=True)] + ["default"]
    if "inforce_pick_req" in ss:                              # set by 'Check and save' / 'Remove'
        ss["inforce_pick"] = ss.pop("inforce_pick_req")
    if ss.get("inforce_pick") not in opts:                    # first visit, or the widget was not drawn last run
        ss["inforce_pick"] = ss.get("inforce_sel") if ss.get("inforce_sel") in opts else opts[0]
    ss["inforce_sel"] = ss["inforce_pick"]
    meta = def_meta if ss["inforce_pick"] == "default" else reg["months"][ss["inforce_pick"]]
    return reg, def_meta, opts, meta


def _inforce_check(host: str, risk_key: str, verify: bool, raw_id: str):
    """Look the ID up in RMS (as an app ID or a long analysis ID). -> (hit dict | None, error text)."""
    if _resolve_inforce is None or _Creds is None:
        return None, "The RMS module did not load, so the ID could not be checked."
    try:
        creds = _Creds(host=host, riskdata_key=risk_key, riskmodeler_key=risk_key, verify=verify)
        return _resolve_inforce(_Http(verify), creds, raw_id, strict=True), ""
    except Exception as exc:                                    # noqa: BLE001
        return None, str(exc)


def _inforce_add(reg: dict, host: str, risk_key: str, verify: bool, as_at: date, raw_id: str, skip_check: bool):
    """Validate and store one month. -> (level, message, saved_key | None)."""
    raw_id = re.sub(r"[\s,._']", "", (raw_id or ""))
    if not raw_id.isdigit():
        return "error", "Enter the analysis ID as a number - the long analysis ID (e.g. 2667825) or the app ID (e.g. 65418).", None
    long_ = len(raw_id) >= 7
    entry = {"as_at": as_at.isoformat(), "id": raw_id, "app_id": "" if long_ else raw_id,
             "analysis_id": raw_id if long_ else "", "name": "", "checked": False,
             "saved": datetime.now().isoformat(timespec="seconds")}
    note = ""
    if skip_check:
        note = "Saved without checking."
    elif not risk_key:
        note = "Saved, but not checked: the Risk Data key is not set, so the ID could not be verified against RMS."
    else:
        hit, err = _inforce_check(host, risk_key, verify, raw_id)
        if not hit:
            return "error", ((err.split(chr(10))[0].rstrip(". ")) or "RMS could not find that analysis") + \
                ". Nothing was saved. Tick 'Save without checking' to keep it anyway.", None
        entry.update(analysis_id=str(hit.get("analysisId") or entry["analysis_id"]),
                     app_id=str(hit.get("appAnalysisId") or entry["app_id"]),
                     name=str(hit.get("analysisName") or ""), checked=True)
    clash = [m for k, m in reg["months"].items()
             if k != entry["as_at"] and _inforce_ids(m) & _inforce_ids(entry)]
    if _inforce_ids(_inforce_default_meta(_secret("INFORCE_ANALYSIS_ID") or DEFAULT_INFORCE_ANALYSIS_ID)) \
            & _inforce_ids(entry):
        clash.append({"as_at": "", "default": True})
    existed = entry["as_at"] in reg["months"]
    reg["months"][entry["as_at"]] = entry
    wrote = _inforce_save(reg)
    msg = f"{'Updated' if existed else 'Added'}: {_inforce_describe(entry)}. "
    if note:
        msg += note + " "
    if wrote == 0:
        msg += "Warning: could not write the list to disk, so it will be lost when the app restarts. "
    level = "success"
    if clash:
        level = "warning"
        msg += ("Note: this is the same analysis as " +
                ", ".join("the default" if m.get("default") else _fmt_asat(m["as_at"]) for m in clash) +
                " - if this month has a new in-force portfolio, enter its new ID.")
    return level, msg, entry["as_at"]


def _inforce_learn(state) -> None:
    """After a successful pull we know the long ID RMS used - remember it so the next run never has to search."""
    try:
        pid = str(((state or {}).get("group") or {}).get("portfolio_id") or "")
        meta = INFORCE
        if not pid.isdigit() or meta.get("default") or meta.get("analysis_id") == pid:
            return
        reg = ss["inforce_reg"]
        if meta.get("as_at") in reg["months"]:
            reg["months"][meta["as_at"]]["analysis_id"] = pid
            _inforce_save(reg)
    except Exception:                                           # noqa: BLE001
        pass

SECTION_STEPS = ["1 · Quote", "2 · Geocode", "3 · RMS run", "4 · Results"]
S_QUOTE, S_GEO, S_RUN, S_RES = SECTION_STEPS
WS_KEYS = ["acc_df", "loc_df", "preview_rows", "geo_failed", "geo_coarse", "rms_import_job", "verify_result",
           "verify_override", "pipeline_state", "res_state", "res_error", "preflight_issues", "auto_pull",
           "launch_error", "allow_ungeocoded", "import_log", "run_stamp", "arch_hash", "save_info", "persist_token",
           "open_notice", "_persist_retry_at"]


def _qp_id(value: str = "") -> None:
    try:
        if value:
            st.query_params["id"] = value
        elif "id" in st.query_params:
            del st.query_params["id"]
    except Exception:                     # noqa: BLE001
        pass


def _blank_draft() -> dict:
    return {
        "account": {"Account Key": "", "Layer Name": "", "Underwriter Initials": "", "Line of Business": "",
                    "Inception Date": date.today().isoformat(),
                    "Expiry Date": (date.today() + timedelta(days=365)).isoformat(),
                    "Share %": 100.0, "Premium": 0, "Policy Limit": 0, "Attachment": 0, "Min Ded": 0, "Max Ded": 0},
        "locations": [LOCATION_INPUT_DEFAULTS.copy()],
    }


def _loc_frame(records) -> pd.DataFrame:
    """Saved location rows -> a DataFrame with exactly the editor's columns and sensible types."""
    df = pd.DataFrame(records or [])
    for col, default in LOCATION_INPUT_DEFAULTS.items():
        if col not in df.columns:
            df[col] = default
    df = df[list(LOCATION_INPUT_DEFAULTS)]
    for col, default in LOCATION_INPUT_DEFAULTS.items():
        if isinstance(default, str):
            df[col] = df[col].fillna(default).astype(str).replace({"nan": default, "None": default})
        else:
            df[col] = pd.to_numeric(df[col], errors="coerce").fillna(default)
    if df.empty:
        df = pd.DataFrame([LOCATION_INPUT_DEFAULTS.copy()])
    return df.reset_index(drop=True)


def _rms_account(a: dict) -> dict:
    inc = date.fromisoformat(a["Inception Date"])
    exp = date.fromisoformat(a["Expiry Date"])
    return {
        "Account Key": a["Account Key"], "Layer Name": a["Layer Name"],
        "Inception Date": inc.strftime("%m/%d/%Y"), "Expiry Date": exp.strftime("%m/%d/%Y"),
        "Underwriter Initials": a["Underwriter Initials"], "Line of Business": a["Line of Business"],
        "Premium": a["Premium"], "Policy Limit": a["Policy Limit"], "Attachment": a["Attachment"],
        "Min Ded": a["Min Ded"], "Max Ded": a["Max Ded"], "Share": float(a["Share %"]) / 100.0, "EQSL Y/N": "N",
    }


def _edm_default(account_key: str) -> str:
    return f"EDM-ANV_{account_key.strip()}_Y{datetime.now().strftime('%y')}" if account_key.strip() else ""


def _draft_tiv(draft) -> float:
    t = 0.0
    for r in draft.get("locations", []):
        if str(r.get("STREETNAME", "")).strip():
            t += safe_num(r.get("Building Value")) + safe_num(r.get("Contents")) + safe_num(r.get("BI"))
    return t


def _derive_status() -> str:
    rs, ps, job = ss.get("res_state"), ss.get("pipeline_state"), ss.get("rms_import_job")
    if rs and rs.get("stage") == "done":
        return "Complete"
    if (ps and ps.get("stage") == "done") or (job and job.get("recovered")):
        return "Analysed"
    if job:
        return "In RMS"
    if "acc_df" in ss:
        return "Geocoded"
    return "Draft"


def _note_save(ok: bool, *, shared=None, local=None, error: str = "", results: bool = False) -> None:
    ss["save_info"] = {"t": datetime.now().strftime("%H:%M:%S"), "ok": ok, "shared": shared, "local": local,
                       "error": error, "results": results}


def _save(include_results: bool | None = None, status: str | None = None) -> str | None:
    """Write the current workspace to the library AND every other copy, then read it back to confirm. Never raises
    into the page and never stores API keys. include_results=None writes the results whenever they are not saved yet."""
    try:
        return _save_inner(include_results, status)
    except Exception as exc:                                         # noqa: BLE001
        if type(exc).__name__ in ("RerunException", "StopException"):
            raise
        _note_save(False, error=f"{type(exc).__name__}: {exc}")
        try:
            st.toast("Could not save this account - see the red badge. Your work is still on screen.")
        except Exception:                                            # noqa: BLE001
            pass
        return ss.get("acct_id")


def _save_inner(include_results, status) -> str | None:
    draft = ss.get("draft")
    if not draft:
        return None
    acct = draft["account"]
    key = str(acct.get("Account Key", "")).strip()
    has_loc = any(str(r.get("STREETNAME", "")).strip() for r in draft.get("locations", []))
    if not key and not has_loc and not ss.get("acct_id"):
        return None
    job, ps, rs = ss.get("rms_import_job"), ss.get("pipeline_state"), ss.get("res_state")
    summary = {"uw": acct.get("Underwriter Initials", ""), "locations": sum(
        1 for r in draft.get("locations", []) if str(r.get("STREETNAME", "")).strip()) or None,
        "tiv": _draft_tiv(draft) or None, "premium": acct.get("Premium") or None}
    done_state = rs if (rs and _anv_store.results_usable(rs)) else None
    if done_state and _summarize_state:
        try:
            summary.update({k: v for k, v in _summarize_state(done_state).items() if v is not None})
        except Exception:                 # noqa: BLE001
            pass
    want_results = bool(done_state) and (include_results is True or (include_results is None and not rs.get("_persisted")))
    eff_status = status or _derive_status()
    if eff_status == "Complete" and not done_state:
        eff_status = "Analysed"                                      # never claim Complete without storable results
    files = None
    if "acc_df" in ss and "loc_df" in ss:
        files = {"acc_csv": ss["acc_df"].to_csv(index=False), "loc_csv": ss["loc_df"].to_csv(index=False),
                 "preview_rows": ss.get("preview_rows", [])}
    stamp = ss.get("run_stamp")
    if files is not None and key and not stamp:
        stamp = ss["run_stamp"] = ARCHIVE.new_stamp()          # a new account run starts here
    run = None
    if job or ps or stamp:
        run = _anv_store.strip_secrets({"job": job, "pipeline": ps, "verify": ss.get("verify_result"),
                                        "verify_override": ss.get("verify_override", False), "archive": stamp})
    results = _anv_store.strip_secrets(done_state) if want_results else None
    # nothing changed since the last confirmed save -> nothing to write
    token = hashlib.md5(_anv_store.pack([draft, files, run, eff_status, summary])).hexdigest()
    if (not want_results and ss.get("acct_id") and ss.get("persist_token") == (ss["acct_id"], token)
            and (ss.get("save_info") or {}).get("ok")):
        return ss["acct_id"]
    acct_id = STORE.upsert(
        ss.get("acct_id") or "", account_key=key, layer=acct.get("Layer Name", ""),
        edm_name=(job or {}).get("edm_name", ""), status=eff_status, summary=summary,
        inputs=draft, files=files, run=run, results=results)
    ss["acct_id"] = acct_id
    _qp_id(acct_id)
    readback_ok = True
    if want_results:
        if STORE.check_results(acct_id) == "ok":                     # read the results back - do not assume
            rs["_persisted"] = True
        else:
            readback_ok = False
    push = STORE.push(ARCHIVE, acct_id)                              # verified copies: shared folder + this server
    safe_elsewhere = bool(push["shared"] or push["local"])
    ss.setdefault("vault_state", {})[acct_id] = "shared" if push["shared"] else ("local" if push["local"] else "none")
    _archive_run(acct_id, stamp, files, run, results, eff_status, draft)
    msgs = []
    if not readback_ok:
        msgs.append("the results were written but could not be read back from the library")
    if not safe_elsewhere:
        msgs.append(push.get("error") or "no second copy could be written")
    elif push["shared"] is False and push.get("error"):
        msgs.append(push["error"])                                   # shared folder failed; the server copy is safe
    ok = readback_ok and safe_elsewhere
    _note_save(ok, shared=push["shared"], local=push["local"], error="; ".join(msgs),
               results=bool(want_results and rs.get("_persisted")))
    if ok:
        ss["persist_token"] = (acct_id, token)
    else:
        ss.pop("persist_token", None)
        try:
            st.toast("Could not confirm the save - see the red badge.")
        except Exception:                                            # noqa: BLE001
            pass
    return acct_id


def _archive_run(acct_id, stamp, files, run, results, status, draft) -> None:
    """Mirror the saved account into its timestamped run folder. Skipped if nothing changed; never raises."""
    if not (acct_id and stamp and files is not None):
        return
    try:
        sig = hashlib.md5(_anv_store.pack([files, run, results, status, draft])).hexdigest()
        if ss.get("arch_hash") == (stamp, sig):
            return
        if not ARCHIVE.on_share:
            ARCHIVE.refresh()                                   # pick the share up again if it has come back
        if STORE.archive_run(ARCHIVE, acct_id, stamp) is not None:
            ss["arch_hash"] = (stamp, sig)
    except Exception:                                           # noqa: BLE001  (saving to the library still worked)
        pass


def _reset_workspace() -> None:
    for k in WS_KEYS:
        ss.pop(k, None)
    ss["nonce"] = ss.get("nonce", 0) + 1
    for k in ("res_persp", "res_ept", "res_rp", "res_mode"):
        ss.pop(k, None)


def _new_quote() -> None:
    _reset_workspace()
    ss["acct_id"] = None
    ss["draft"] = _blank_draft()
    ss["view"] = "workspace"
    ss["ws_step_req"] = S_QUOTE
    _qp_id("")


def _open_account(acct_id: str) -> bool:
    _sync_library(only=acct_id)                          # pull a newer / missing copy from any location first
    rec = STORE.get(acct_id)
    if rec and (rec.get("_damaged") or (rec.get("status") == "Complete"
                                        and not _anv_store.results_usable(rec.get("results")))):
        if STORE.repair(ARCHIVE, acct_id):               # damaged / empty entry -> a verified copy from another folder
            rec = STORE.get(acct_id)
    if not rec:
        return False
    _reset_workspace()
    ss["acct_id"] = acct_id
    ss["draft"] = rec.get("inputs") or _blank_draft()
    ss["draft"].setdefault("locations", [LOCATION_INPUT_DEFAULTS.copy()])
    files = rec.get("files") or {}
    if files.get("acc_csv") and files.get("loc_csv"):
        rd = dict(dtype=str, keep_default_na=False)
        ss["acc_df"] = pd.read_csv(io.StringIO(files["acc_csv"]), **rd)
        ss["loc_df"] = pd.read_csv(io.StringIO(files["loc_csv"]), **rd)
        ss["preview_rows"] = files.get("preview_rows", [])
        failed, coarse = geocode_quality(ss["preview_rows"])
        ss["geo_failed"], ss["geo_coarse"] = failed, coarse
    run = rec.get("run") or {}
    if run.get("archive"):
        ss["run_stamp"] = run["archive"]
    if run.get("job"):
        ss["rms_import_job"] = run["job"]
    if run.get("pipeline"):
        ss["pipeline_state"] = run["pipeline"]
    if run.get("verify"):
        ss["verify_result"] = run["verify"]
    ss["verify_override"] = bool(run.get("verify_override"))
    res = rec.get("results")
    notes = []
    if rec.get("_damaged"):
        notes.append("Part of this saved account could not be read (" + ", ".join(rec["_damaged"]) + ").")
    if res and _anv_store.results_usable(res):
        res["from_library"] = rec.get("updated", "")
        res["_persisted"] = True                          # it came out of the library, so it is already saved
        ss["res_state"] = res
    else:
        if res:
            notes.append("The saved results are incomplete.")
        elif rec.get("status") == "Complete":
            notes.append("This account is marked Complete but its saved results are missing.")
        job = ss.get("rms_import_job") or {}
        if job.get("exposure_id") and (rec.get("status") in ("Complete", "Analysed") or res):
            ss["auto_pull"] = True                        # the analysis exists in RMS: rebuild the results from it
            notes.append("They are rebuilt from RMS automatically (this needs the Risk Data key).")
    if notes:
        ss["open_notice"] = " ".join(notes)
    ss["view"] = "workspace"
    ss["ws_step_req"] = (S_RES if ("res_state" in ss or ss.get("auto_pull")) else S_RUN if "rms_import_job" in ss
                         else S_GEO if "acc_df" in ss else S_QUOTE)
    _qp_id(acct_id)
    return True


def _goto(step: str) -> None:
    ss["ws_step_req"] = step
    st.rerun()


def _uk(iso: str) -> str:
    try:
        return datetime.fromisoformat(iso).strftime("%d/%m/%Y %H:%M")
    except Exception:                     # noqa: BLE001
        return iso or ""


def _cmp(v, cur: str = "") -> str:
    n = None
    try:
        n = float(v)
    except (TypeError, ValueError):
        pass
    if n is None:
        return "-"
    a = abs(n)
    s = f"{n / 1e9:,.2f}B" if a >= 1e9 else f"{n / 1e6:,.2f}M" if a >= 1e6 else f"{n / 1e3:,.0f}K" if a >= 1e4 else f"{n:,.0f}"
    return f"{cur} {s}".strip()


def _badge(status: str) -> str:
    cls = {"Complete": "ok", "Analysed": "ok", "In RMS": "run", "Geocoded": "warn", "Draft": ""}.get(status, "")
    return f'<span class="badge {cls}">{status}</span>'


def _sec(title: str) -> None:
    st.markdown(f'<div class="h-sec">{title}</div>', unsafe_allow_html=True)


# --------------------------------------------------------------------------
# First load: deep link ?id=... opens that account
# --------------------------------------------------------------------------
if "booted" not in ss:
    ss["booted"] = True
    ss["view"] = "library"
    with st.spinner("Checking the saved-results library..."):
        _sync_library(force=True)                      # a restart / new server / redeploy never leaves the library empty
    _q = st.query_params.get("id") if hasattr(st, "query_params") else None
    if isinstance(_q, str) and _q.strip():
        if not _open_account(_q.strip()):
            _qp_id("")
if "draft" not in ss:
    ss["draft"] = _blank_draft()
ss.setdefault("nonce", 0)
if "inforce_reg" not in ss:
    ss["inforce_reg"] = _inforce_load()

# --------------------------------------------------------------------------
# Sidebar: navigation + connection + analysis settings
# --------------------------------------------------------------------------
with st.sidebar:
    st.markdown('<div class="sb-brand">ANV<i>.</i></div><div class="sb-sub">PacificPoint &middot; EQ Quote Desk</div>',
                unsafe_allow_html=True)
    _n1, _n2 = st.columns(2)
    if _n1.button("Accounts", key="nav_lib", width="stretch",
                  type="primary" if ss.get("view") == "library" else "secondary"):
        if ss.get("view") == "workspace":
            _save()
        ss["view"] = "library"
        _qp_id("")
        st.rerun()
    if _n2.button("New quote", key="nav_new", width="stretch"):
        if ss.get("view") == "workspace":
            _save()
        _new_quote()
        st.rerun()

    st.markdown('<div class="sb-h">RMS connection</div>', unsafe_allow_html=True)
    host = st.text_input("Host", value=_secret("RMS_HOST") or "api-euw1.rms.com",
                         help="Your tenant's RMS host - shared by all the APIs below.")
    api_key, _s1 = _key_box("Location Intelligence key", "LI_API_KEY",
                            "Geocoding and the hazard lookups (li/* endpoints).")
    rms_import_api_key, _s2 = _key_box("Risk Data key", "RISKDATA_API_KEY",
                                       "EDM creation, import, analysis and results (riskdata / riskmodeler endpoints).")
    grouping_api_key, _s3 = _key_box("Grouping key", "GROUPING_API_KEY",
                                     "Marginal impact (platform/grouping/v1). Its own dedicated key.")
    _reg, _def_meta, _opts, INFORCE = _inforce_state()          # picked at the top of the main page, not here
    inforce_analysis_id = _inforce_effective_id(INFORCE)         # the long ID whenever it is known: no search needed
    st.caption("In-force portfolio: " + _inforce_label(INFORCE) + "  (change it at the top of the page)")
    grouping_rg_id = _secret("GROUPING_RESOURCE_GROUP_ID")
    verify_ssl = True
    rms_import_verify_ssl = verify_ssl
    rms_import_host = host
    _n_saved = sum([_s1, _s2, _s3])
    if _n_saved:
        st.caption(f"{_n_saved} of 3 keys loaded from Secrets.")
    _render_connection_test(host, api_key, rms_import_api_key, grouping_api_key, grouping_rg_id,
                            inforce_analysis_id, verify_ssl)

    with st.expander("Analysis settings"):
        st.caption("Defaults come from the confirmed Controls block of the source workbook. "
                   "A wrong profile or scheme ID silently gives a wrong result - change with care.")
        model_profile_id = st.number_input("Model profile ID", value=CONFIRMED_DEFAULTS["model_profile_id"], step=1)
        event_rate_scheme_id = st.number_input("Event rate scheme ID", value=CONFIRMED_DEFAULTS["event_rate_scheme_id"], step=1)
        output_profile_id = st.number_input("Output profile ID", value=CONFIRMED_DEFAULTS["output_profile_id"], step=1)
        vintage = st.text_input("Vintage", value=CONFIRMED_DEFAULTS["vintage"])
        geohaz_engine_type = st.text_input("Geohaz engine type", value=CONFIRMED_DEFAULTS["geohaz_engine_type"])
        geohaz_engine_version = st.text_input("Geohaz engine version", value=CONFIRMED_DEFAULTS["geohaz_engine_version"],
                                              help="RMS requires one decimal place, e.g. '25.0'.")
        hazard_layer_name = st.text_input("Hazard layer", value=CONFIRMED_DEFAULTS["hazard_layer_name"])
        skip_prev_geocoded = st.checkbox("Skip re-geocoding in RMS (locations already have coordinates)", value=True)

    with st.expander("Keys saved once, not retyped"):
        st.markdown("In Streamlit Cloud: **Manage app > Settings > Secrets**. On Posit Connect: **Vars** tab "
                    "(environment variables) or the same names in `.streamlit/secrets.toml`.")
        st.code('LI_API_KEY = "..."\nRISKDATA_API_KEY = "..."\nGROUPING_API_KEY = "..."\n'
                '# optional\nINFORCE_ANALYSIS_ID = "65418"\nRMS_HOST = "api-euw1.rms.com"\n'
                'STORE_DIR = "/path/that/persists"\n'
                'ARCHIVE_DIR = "/mnt/from-posit/content/anv-eq-rms-modeller"   # default, only set to override',
                language="toml")
    st.caption(f"Library: {len(STORE.list())} account(s)")
    if ARCHIVE.on_share:
        st.caption(":green[●] Every save is also copied to the shared folder")
    else:
        st.caption(":red[●] Shared folder not usable - saving on this server only")


