# --------------------------------------------------------------------------
# Main-page bar: Accounts / New quote / In-force portfolio. Does not depend on the sidebar being open.
# --------------------------------------------------------------------------
def _main_bar() -> None:
    reg, def_meta, opts, meta = _inforce_state()
    n1, n2, n3 = st.columns([1, 1, 3])
    if n1.button("Accounts", key="nav_lib_m", width="stretch", type="primary" if ss.get("view") == "library" else "secondary"):
        if ss.get("view") == "workspace":
            _save()
        ss["view"] = "library"
        _qp_id("")
        st.rerun()
    if n2.button("New quote", key="nav_new_m", width="stretch"):
        if ss.get("view") == "workspace":
            _save()
        _new_quote()
        st.rerun()
    with n3.popover("In-force portfolio:  " + _inforce_label(meta)):
        st.selectbox(
            "In-force portfolio as at", opts, key="inforce_pick",
            format_func=lambda k: _inforce_label(def_meta if k == "default" else reg["months"][k]),
            help="The in-force portfolio Marginal Impact compares every quote against. Pick the month's portfolio; "
                 "add a new month below when it is available. 'Default' is the standing ID.")
        st.caption(_inforce_describe(meta))
        if not meta.get("analysis_id"):
            st.caption("Tip: the long analysis ID (e.g. 2667825) is the quickest and most reliable to use.")
        st.markdown("**Add or update a month**")
        st.caption("Month-end date, and that month's in-force portfolio ID - the long analysis ID (e.g. 2667825) or the "
                   "short app ID (e.g. 65418). Either works. Adding a month selects it.")
        _asat = st.date_input("Portfolio as at", value=date.today().replace(day=1) - timedelta(days=1),
                              format="DD/MM/YYYY", key="inf_new_date")
        _newid = st.text_input("Analysis ID", key="inf_new_id", placeholder="e.g. 2667825 or 65418")
        _skip = st.checkbox("Save without checking in RMS", key="inf_new_skip")
        if st.button("Check and save", key="inf_new_btn", width="stretch", type="primary"):
            _lvl, _txt, _key = _inforce_add(reg, host, rms_import_api_key, True, _asat, _newid, _skip)
            ss["inforce_msg"] = (_lvl, _txt)
            if _key:
                ss["inforce_pick_req"] = _key
            st.rerun()
        if ss.get("inforce_pick") != "default" and st.button("Remove the selected month", key="inf_del", width="stretch"):
            reg["months"].pop(ss.get("inforce_pick"), None)
            _inforce_save(reg)
            ss["inforce_msg"] = ("info", f"Removed {_fmt_asat(ss.get('inforce_pick'))}.")
            ss["inforce_pick_req"] = "default"
            st.rerun()
    _m = ss.pop("inforce_msg", None)
    if _m:
        {"success": st.success, "warning": st.warning, "error": st.error}.get(_m[0], st.info)(_m[1])


_main_bar()



