def _storage_panel(rows) -> None:
    """Where results are kept, whether it is working, and - if not - exactly why."""
    with st.expander("Storage health", expanded=not ARCHIVE.on_share):
        rep_ = ss.get("sync_report") or {}
        vc = {n: len(v.metas()) for n, v in ARCHIVE.vaults()}
        local_n = max([c for n, c in vc.items() if n != "shared"] or [0])
        st.markdown(
            "| Item | Detail |\n|---|---|\n"
            f"| Library database | `{STORE.path}`  -  {STORE.kind_note} |\n"
            f"| Shared folder | `{ARCHIVE.share_root}`  -  " + ("**connected**" if ARCHIVE.on_share else "**NOT usable**") + " |\n"
            f"| Copies on this server | {len(ARCHIVE.local_roots)} folder(s): " + ", ".join(f"`{p}`" for p in ARCHIVE.local_roots) + " |\n"
            f"| Accounts | {len(rows)} in the database, {vc.get('shared', 'n/a')} in the shared folder, {local_n} in server copies |\n"
            f"| Last check | {_uk(rep_.get('at', '')) or 'not yet'} - {rep_.get('pulled', 0)} restored, "
            f"{rep_.get('pushed', 0)} copied out, {rep_.get('removed', 0)} removed |")
        for e_ in (rep_.get("errors") or [])[:4]:
            st.error(e_)
        if rep_.get("unreadable"):
            st.error(f"{len(rep_['unreadable'])} saved copy(ies) could not be read and were skipped.")
        lg = ss.get("legacy_report") or {}
        if lg.get("error"):
            st.warning("Older run folders could not be merged: " + lg["error"])
        elif lg.get("scanned"):
            st.caption(f"Older run folders merged: {lg.get('added', 0)} added, {lg.get('updated', 0)} updated.")

        _sm = ss.pop("share_msg", None)
        if _sm:
            {"success": st.success, "error": st.error}.get(_sm[0], st.info)(_sm[1])
        if not ARCHIVE.on_share:
            dg = ARCHIVE.diagnose()
            st.error("**Why the shared folder is not working:** " + dg["verdict"])
            st.markdown(
                "| Item | Detail |\n|---|---|\n"
                f"| Folder tried | `{dg['path']}` |\n"
                f"| This app runs as | {dg['user']} |\n"
                f"| Nearest folder that exists | `{dg['nearest']}`  (mode {dg['nearest_mode']}, owner {dg['nearest_owner']}) |\n"
                f"| Error | {dg['write_error'] or dg['error'] or '-'} |\n"
                "| Mounted drives seen | " + (", ".join(f"`{m}`" for m in dg["mounts"]) or "none under /mnt, /srv or /data") + " |\n"
                "| Inside /mnt | " + (", ".join(f"`{Path(m['name']).name}`" + (" (mount)" if m["mount"] else "") for m in dg["mnt"]) or "empty or not present") + " |")
            st.caption("Send the table above to whoever looks after Posit Connect - it is exactly what they need. Until the "
                       "share works, results are kept on this server and can be backed up with the download button.")
            s1, s2 = st.columns([3, 1.4])
            _try = s1.text_input("Try a different folder", key="sh_try", placeholder="/mnt/...",
                                 label_visibility="collapsed")
            if s2.button("Use this folder", key="sh_use", width="stretch"):
                _ok, _err = ARCHIVE.set_share(_try)
                if _ok:
                    _sync_library(force=True)
                    ss["share_msg"] = ("success", f"Now using {ARCHIVE.share_root}. Everything saved so far has been copied there.")
                else:
                    ss["share_msg"] = ("error", f"Could not use that folder: {_err}")
                st.rerun()
            if st.button("Look for folders this app can write to", key="sh_scan"):
                with st.spinner("Looking..."):
                    ss["sh_found"] = _anv_store.Archive.scan_writable()
            _fnd = ss.get("sh_found")
            if _fnd is not None:
                if not _fnd:
                    st.info("No writable folders were found under /mnt, /srv, /data or /shared.")
                for _i, f_ in enumerate(_fnd):
                    f1, f2 = st.columns([4, 1.4])
                    f1.markdown(f"`{f_['path']}`" + ("  (mounted drive)" if f_["mount"] else ""))
                    if f2.button("Use", key=f"sh_pick_{_i}", width="stretch"):
                        _ok, _err = ARCHIVE.set_share(f_["path"] + "/anv-eq-rms-modeller")
                        ss["share_msg"] = (("success", f"Now using {ARCHIVE.share_root}.") if _ok
                                           else ("error", f"Could not use that folder: {_err}"))
                        if _ok:
                            _sync_library(force=True)
                        st.rerun()
            st.caption("To make a folder permanent, add a variable named ARCHIVE_DIR (Connect: Vars tab) with its path.")
        h1, h2, h3 = st.columns(3)
        if h1.button("Sync now", key="st_sync", width="stretch"):
            ARCHIVE.refresh()
            _sync_library(force=True)
            st.rerun()
        if h2.button("Check and repair", key="st_deep", width="stretch",
                     help="Reads every saved account back, repairs damaged ones from another copy, and re-copies "
                          "anything missing."):
            with st.spinner("Checking every account..."):
                ARCHIVE.refresh()
                ss["deep_report"] = STORE.deep_check(ARCHIVE)
            _sync_library(force=True)
        if h3.button("Re-check shared folder", key="st_share", width="stretch"):
            ARCHIVE.refresh()
            st.rerun()
        dr = ss.get("deep_report")
        if dr:
            if not (dr["damaged"] or dr.get("vault_bad") or dr.get("vault_fixed")):
                st.success(f"Checked {dr['checked']} account(s): all saved results read back correctly.")
            else:
                if dr["repaired"]:
                    st.success("Repaired from another copy: " + ", ".join(dr["repaired"]))
                if dr.get("vault_fixed"):
                    st.success("Re-wrote damaged copies: " + ", ".join(dr["vault_fixed"]))
                if dr["unrepaired"]:
                    st.error("Could not repair (no good copy anywhere): " + ", ".join(dr["unrepaired"]) +
                             ". Open each one and use Pull results to rebuild it from RMS.")
                if dr.get("vault_bad"):
                    st.error("Damaged and could not be re-written: " + ", ".join(dr["vault_bad"]))


def _library_view():
    _sync_library()                                      # at most every 30 s; also heals a wiped / different server
    _storage_banner(with_backup=True)
    rows = STORE.list()
    if not rows:
        st.markdown("**No accounts on this server yet.** If you have run accounts before, restore them in one of three "
                    "ways: a backup file (below), the shared folder once it is working (see Storage health), or straight "
                    "from RMS with *Open a run that is not in the library yet* - the analysis is still in RMS, so its "
                    "results can always be rebuilt.")
        _up0 = st.file_uploader("Restore from a backup file", type=["json"], key="bk_up_empty")
        if _up0 is not None and st.button("Restore this backup", key="bk_go_empty", type="primary"):
            try:
                _a0, _u0 = STORE.import_all(_up0.getvalue())
                _sync_library(force=True)
                st.success(f"Restored: {_a0} added, {_u0} updated.")
                st.rerun()
            except Exception as exc:                          # noqa: BLE001
                st.error(f"Could not restore: {exc}")
    st.markdown('<div class="pg-title">Accounts</div><div class="pg-sub">Every quote you run is saved here - '
                'open one to see its results again without re-running anything.</div>', unsafe_allow_html=True)

    done = sum(1 for r in rows if r["status"] == "Complete" and r.get("has_results"))
    broken = [r for r in rows if r["status"] == "Complete" and not r.get("has_results")]
    prog = sum(1 for r in rows if r["status"] in ("In RMS", "Analysed", "Geocoded"))
    drafts = sum(1 for r in rows if r["status"] == "Draft")
    if _kpis and rows:
        st.markdown(_kpis([("Accounts", f"{len(rows):,}", "in the library", NAVY),
                           ("Complete", f"{done:,}", "results saved", "#2E7D5B"),
                           ("In progress", f"{prog:,}", "geocoded / in RMS / analysed", GOLD),
                           ("Drafts", f"{drafts:,}", "not yet run", "#8A94A6")]), unsafe_allow_html=True)

    if broken:
        st.warning(f"{len(broken)} account(s) are marked Complete but their saved results are missing "
                   f"({', '.join((r['account_key'] or '?') for r in broken[:5])}{'...' if len(broken) > 5 else ''}). "
                   "Open one to rebuild its results from RMS, or run 'Check and repair' under Storage health.")
    c1, c2, c3 = st.columns([3, 3, 1.6])
    q = c1.text_input("Search", placeholder="Account key, layer, EDM...", label_visibility="collapsed", key="lib_q")
    flt = c2.segmented_control("Show", ["All", "Complete", "In progress", "Draft"], default="All",
                               label_visibility="collapsed", key="lib_flt") if hasattr(st, "segmented_control") else "All"
    if c3.button("New quote", type="primary", width="stretch", key="lib_new"):
        _new_quote()
        st.rerun()

    flt = flt or "All"
    ql = (q or "").strip().lower()
    view = []
    for r in rows:
        if flt == "Complete" and r["status"] != "Complete":
            continue
        if flt == "In progress" and r["status"] not in ("In RMS", "Analysed", "Geocoded"):
            continue
        if flt == "Draft" and r["status"] != "Draft":
            continue
        if ql and ql not in " ".join(str(r.get(k, "")) for k in ("account_key", "layer", "edm_name", "status")).lower():
            continue
        view.append(r)

    if not rows:
        st.markdown('<div class="empty"><b>No accounts yet</b><div>Start a new quote - once its analysis has run, '
                    'the results are kept here.</div></div>', unsafe_allow_html=True)
    elif not view:
        st.info("Nothing matches that search.")
    else:
        recs = []
        for r in view:
            s = r["summary"] or {}
            cur = s.get("currency") or ""
            mi = s.get("mi_pct")
            recs.append({
                "Account": r["account_key"] or "(unnamed)", "Layer": r["layer"] or "", "UW": s.get("uw") or "",
                "Locations": s.get("locations") or None, "TIV": _cmp(s.get("tiv"), cur),
                "Quote AAL": _cmp(s.get("aal"), cur),
                f"Marginal impact (1 in {s.get('rp', 250)})": f"{mi * 100:+.3f}%" if isinstance(mi, (int, float)) else "-",
                "Status": r["status"] if (r["status"] != "Complete" or r.get("has_results")) else "Results missing",
                "Saved": {"shared": "Shared folder", "local": "This server only", "none": "Not backed up"}.get(
                    (ss.get("vault_state") or {}).get(r["id"]), "-"),
                "Updated": _uk(r["updated"]),
            })
        df = pd.DataFrame(recs)
        ev = st.dataframe(df, hide_index=True, width="stretch", on_select="rerun", selection_mode="single-row",
                          key="lib_tbl", height=int(min(38 + 35 * len(df), 560)))
        sel = list(getattr(getattr(ev, "selection", None), "rows", []) or [])
        if sel:
            rec = view[sel[0]]
            a1, a2, a3, a4 = st.columns([1.4, 1.4, 1.4, 4])
            if a1.button("Open", type="primary", width="stretch", key="lib_open"):
                if _open_account(rec["id"]):
                    st.rerun()
                st.error("Could not open that account.")
            if a2.button("Duplicate", width="stretch", key="lib_dup", help="New draft with the same inputs - for re-quoting."):
                nid = STORE.duplicate(rec["id"])
                if nid:
                    _open_account(nid)
                    st.rerun()
            with a3.popover("Delete"):
                st.write(f"Delete **{rec['account_key'] or 'this account'}** from the library? "
                         "Nothing is removed from RMS.")
                if st.button("Yes, delete", key="lib_del"):
                    STORE.delete(rec["id"], ARCHIVE)
                    ss.get("vault_state", {}).pop(rec["id"], None)
                    st.rerun()
        else:
            st.caption("Select a row to open, duplicate or delete it.")

    _storage_panel(rows)
    with st.expander("Open a run that is not in the library yet", expanded=not rows):
        st.caption("For analyses run before the library existed: load them from RMS by EDM name. "
                   "The account is then saved here automatically.")
        e1, e2, e3 = st.columns([3, 2, 1.4])
        edm_in = e1.text_input("EDM name", placeholder="EDM-ANV_25M_1234_Y26", key="rec_edm")
        acct_in = e2.text_input("Account key (blank = taken from the EDM name)", key="rec_acct")
        e3.markdown('<div style="height:1.7rem"></div>', unsafe_allow_html=True)
        if e3.button("Load", key="rec_go", width="stretch"):
            _load_from_rms(edm_in, acct_in)

    with st.expander("Backup and restore"):
        st.caption(f"The library database is on the app server ({STORE.path}). Every run is also saved to a "
                   f"timestamped folder: {ARCHIVE.label}.")
        if st.button("Restore library from the run folders", key="bk_arch", disabled=not ARCHIVE.on_share,
                     help="Reads the saved run folders back into the library. Newer copies win."):
            try:
                added, updated = STORE.restore_from_archive(ARCHIVE)
                st.success(f"Restored from run folders: {added} added, {updated} updated.")
            except Exception as exc:                          # noqa: BLE001
                st.error(f"Could not restore: {exc}")
        b1, b2 = st.columns(2)
        b1.download_button("Download library backup", data=STORE.export_all(), width="stretch",
                           file_name=f"ANV_quote_library_{datetime.now():%Y%m%d_%H%M}.json", mime="application/json",
                           key="bk_dl")
        up = b2.file_uploader("Restore from a backup file", type=["json"], key="bk_up", label_visibility="collapsed")
        if up is not None and st.button("Restore this backup", key="bk_go"):
            try:
                added, updated = STORE.import_all(up.getvalue())
                st.success(f"Restored: {added} added, {updated} updated.")
            except Exception as exc:                          # noqa: BLE001
                st.error(f"Could not restore: {exc}")


def _load_from_rms(edm: str, acct: str) -> None:
    edm = (edm or "").strip()
    if not rms_import_api_key:
        st.error("The Risk Data key is not set. Add RISKDATA_API_KEY (Posit Connect: Vars tab) or use the sidebar.")
        return
    if not edm:
        st.error("Enter the EDM name.")
        return
    if _Creds is None:
        st.error("The RMS module did not load.")
        return
    creds = _Creds(host=host, riskdata_key=rms_import_api_key, riskmodeler_key=rms_import_api_key, verify=verify_ssl)
    with st.spinner("Looking the EDM up in RMS..."):
        eid = _resolve_exposure_id(_Http(verify_ssl), creds, edm)
    if not eid:
        st.error(f"No EDM named '{edm}' was found. Check the spelling and that the Risk Data key is for the right tenant.")
        return
    acct = (acct or "").strip() or _account_from_edm(edm)
    if not acct:
        st.error("That EDM exists, but its name does not follow EDM-ANV_<account>_Y<yy> - type the account key as well.")
        return
    _reset_workspace()
    ss["acct_id"] = None
    d = _blank_draft()
    d["account"]["Account Key"] = acct
    ss["draft"] = d
    ss["rms_import_job"] = {"job_id": "", "exposure_id": eid, "portfolio_id": "", "edm_name": edm, "status_url": "",
                            "import_status": "COMPLETED", "recovered": True}
    ss["auto_pull"] = True
    ss["view"] = "workspace"
    ss["ws_step_req"] = S_RES
    _save()
    st.rerun()


